            ', descripcion=',
            COALESCE(OLD.description, 'NULL'),
            ', precio=',
            OLD.current_price,
            ', stock=',
            OLD.current_stock,
            ', status=',
            COALESCE(CAST(OLD.status AS UNSIGNED), 0)
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
